def obtener_estilo(modo_oscuro=False):
    archivo_qss = "estilos_oscuros.qss" if modo_oscuro else "estilos.qss"

    # 1. Probar en sys._MEIPASS (si corre compilado y el archivo fue empaquetado)
    if hasattr(sys, '_MEIPASS'):
        candidato = os.path.join(sys._MEIPASS, archivo_qss)
        if os.path.exists(candidato):
            try:
                with open(candidato, "r", encoding="utf-8") as f:
                    return f.read()
            except Exception:
                pass

    # 2. Probar en el directorio del ejecutable o script
    try:
        dir_exe = os.path.dirname(os.path.abspath(sys.argv[0]))
        candidato = os.path.join(dir_exe, archivo_qss)
        if os.path.exists(candidato):
            try:
                with open(candidato, "r", encoding="utf-8") as f:
                    return f.read()
            except Exception:
                pass
    except Exception:
        pass

    # 3. Probar en la ruta de trabajo actual
    if os.path.exists(archivo_qss):
        try:
            with open(archivo_qss, "r", encoding="utf-8") as f:
                return f.read()
        except Exception:
            pass

    # 4. Fallback integrado en código Python (garantizado contra omisiones de empaquetado)
    return ESTILOS_OSCUROS_EMBEBIDOS if modo_oscuro else ESTILOS_CLAROS_EMBEBIDOS
